    24	
    25	/** The HTTP API the inn's website and front desk call. */
    26	public final class HttpApi {
    27	
    28	    private final Javalin server;
    29	    private final Rooms rooms;
    30	    private final ReservationService reservations;
    31	    private final SentMessages sentMessages;
    32	    private final OccupancyReport occupancyReport;
    33	    private final RevenueReport revenueReport;
    34	
    35	    public HttpApi(
    36	            Rooms rooms,
    37	            ReservationService reservations,
    38	            SentMessages sentMessages,
    39	            OccupancyReport occupancyReport,
    40	            RevenueReport revenueReport) {
    41	        this.rooms = rooms;
    42	        this.reservations = reservations;
    43	        this.sentMessages = sentMessages;
    44	        this.occupancyReport = occupancyReport;
    45	        this.revenueReport = revenueReport;
    46	
    47	        ObjectMapper jsonMapper = JsonMapper.builder()
    48	                .addModule(new JavaTimeModule())
    49	                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
    50	                .build();
    51	        this.server = Javalin.create(config -> {
    52	            config.showJavalinBanner = false;
    53	            config.jsonMapper(new JavalinJackson(jsonMapper, false));
    54	        });
    55	        registerRoutes();
    56	        registerErrorHandling();
    57	    }
    58	
    59	    public Javalin server() {
    60	        return server;
    61	    }
    62	
    63	    private void registerRoutes() {
    64	        server.get("/rooms", ctx -> ctx.json(rooms.all()));
    65	
    66	        server.post("/reservations", ctx -> {
    67	            NewReservation request = readNewReservation(ctx);
    68	            ctx.status(201).json(new ReservationResponse(reservations.create(request)));
    69	        });
    70	        server.get("/reservations/{id}", ctx ->
    71	                ctx.json(new ReservationResponse(reservations.find(reservationId(ctx)))));
    72	        server.post("/reservations/{id}/confirmation", ctx ->
    73	                ctx.json(new ReservationResponse(reservations.confirm(reservationId(ctx)))));
    74	        server.post("/reservations/{id}/cancellation", ctx ->
    75	                ctx.json(new ReservationResponse(reservations.cancel(reservationId(ctx)))));
    76	        server.post("/reservations/{id}/check-in", ctx ->
    77	                ctx.json(new ReservationResponse(reservations.checkIn(reservationId(ctx)))));
    78	        server.post("/reservations/{id}/check-out", ctx ->
    79	                ctx.json(reservations.checkOut(reservationId(ctx))));
    80	        server.get("/reservations/{id}/document", ctx ->
    81	                ctx.json(reservations.receiptCopy(reservationId(ctx))));
    82	
    83	        server.get("/messages", ctx -> ctx.json(sentMessages.all()));
    84	
    85	        server.get("/reports/occupancy", ctx -> {
    86	            LocalDate night = readDate(ctx);
    87	            ctx.contentType("text/csv; charset=utf-8").result(occupancyReport.generate(night));
    88	        });
    89	        server.get("/reports/revenue", ctx -> {
    90	            YearMonth month = readMonth(ctx);
    91	            ctx.contentType("text/csv; charset=utf-8").result(revenueReport.generate(month));
    92	        });
    93	    }
    94	
    95	    private void registerErrorHandling() {
    96	        server.exception(HotelException.class, (exception, ctx) -> {
    97	            ctx.status(httpStatus(exception.errorCode()));
    98	            ctx.json(new ErrorResponse(exception.errorCode().name(), exception.getMessage()));
    99	        });
   100	    }
   101	
   102	    private static int httpStatus(ErrorCode errorCode) {
   103	        return switch (errorCode) {
   104	            case INVALID_REQUEST -> 400;
   105	            case ROOM_NOT_FOUND, RESERVATION_NOT_FOUND -> 404;
   106	            case ROOM_UNAVAILABLE, OPERATION_NOT_ALLOWED -> 409;
   107	            case CAPACITY_EXCEEDED -> 422;
   108	        };
   109	    }
   110	
   111	    private static NewReservation readNewReservation(Context ctx) {
   112	        CreateReservationRequest body;
   113	        try {
   114	            body = ctx.bodyAsClass(CreateReservationRequest.class);
   115	        } catch (Exception unreadableBody) { // Jackson's own exceptions are checked, but reach here unwrapped
   116	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the body is not a valid reservation request");
   117	        }
   118	        if (body == null
   119	                || body.roomNumber() == null
   120	                || isBlank(body.guestName())
   121	                || isBlank(body.guestEmail())
   122	                || body.checkIn() == null
   123	                || body.checkOut() == null
   124	                || body.guests() == null
   125	                || body.ratePlan() == null) {
   126	            throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
   127	        }
   128	        Identification identification = Identifications.fromRequest(new Identifications.Fields(
   129	                body.guestCpf(), body.companyCnpj(), body.companyName(), body.guestPassport(), body.guestCountry()));
   130	        Guest guest = new Guest(body.guestName(), body.guestEmail(), identification);
   131	        return new NewReservation(
   132	                body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(), body.ratePlan());
   133	    }
   134	
   135	    private static long reservationId(Context ctx) {
   136	        String id = ctx.pathParam("id");
   137	        try {
   138	            return Long.parseLong(id);
   139	        } catch (NumberFormatException notANumber) {
   140	            throw new HotelException(ErrorCode.RESERVATION_NOT_FOUND, "reservation " + id + " does not exist");
   141	        }
   142	    }
   143	
   144	    private static LocalDate readDate(Context ctx) {
   145	        String date = requiredQueryParam(ctx, "date");
   146	        try {
   147	            return LocalDate.parse(date);
   148	        } catch (DateTimeParseException badDate) {
   149	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + date + "' is not a date (yyyy-MM-dd)");
   150	        }
   151	    }
   152	
   153	    private static YearMonth readMonth(Context ctx) {
   154	        String month = requiredQueryParam(ctx, "month");
   155	        try {
   156	            return YearMonth.parse(month);
   157	        } catch (DateTimeParseException badMonth) {
   158	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + month + "' is not a month (yyyy-MM)");
   159	        }
   160	    }
