   162	    private static String requiredQueryParam(Context ctx, String name) {
   163	        String value = ctx.queryParam(name);
   164	        if (value == null) {
   165	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the query parameter '" + name + "' is required");
   166	        }
   167	        return value;
   168	    }
