   104	            case INVALID_REQUEST -> 400;
   105	            case ROOM_NOT_FOUND, RESERVATION_NOT_FOUND -> 404;
   106	            case ROOM_UNAVAILABLE, OPERATION_NOT_ALLOWED -> 409;
   107	            case CAPACITY_EXCEEDED -> 422;
