   112	        CreateReservationRequest body;
   113	        try {
   114	            body = ctx.bodyAsClass(CreateReservationRequest.class);
   115	        } catch (Exception unreadableBody) { // Jackson's own exceptions are checked, but reach here unwrapped
   116	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the body is not a valid reservation request");
