     1	package hotel.reservations;
     2	
     3	import java.math.BigDecimal;
     4	import java.sql.Connection;
     5	import java.sql.Date;
     6	import java.sql.PreparedStatement;
     7	import java.sql.ResultSet;
     8	import java.sql.SQLException;
     9	import java.time.LocalDate;
    10	import java.util.ArrayList;
    11	import java.util.List;
    12	import java.util.Optional;
    13	import javax.sql.DataSource;
    14	
    15	/** Keeps the reservations in the database. */
    16	public final class ReservationStore {
    17	
    18	    private static final String COLUMNS = "id, room_number, guest_name, guest_email, "
    19	            + "identification_type, identification_number, identification_detail, check_in, check_out, guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund";
    20	    /** PostgreSQL's code for a broken exclusion constraint: here, the room was already booked on one of the nights. */
    21	    private static final String EXCLUSION_VIOLATION = "23P01";
    22	
    23	    private final DataSource dataSource;
    24	
    25	    public ReservationStore(DataSource dataSource) {
    26	        this.dataSource = dataSource;
    27	    }
    28	
    29	    /** Saves a new reservation; the database numbers it. */
    30	    Reservation add(NewReservation request, Price price) {
    31	        String insert = "INSERT INTO reservations (room_number, guest_name, guest_email, "
    32	                + "identification_type, identification_number, identification_detail, check_in, check_out, guests, "
    33	                + "rate_plan, nights, subtotal, discount, total, status, amount_paid) "
    34	                + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) RETURNING id";
    35	        try (Connection connection = dataSource.getConnection();
    36	                PreparedStatement statement = connection.prepareStatement(insert)) {
    37	            statement.setInt(1, request.roomNumber());
    38	            statement.setString(2, request.guest().name());
    39	            statement.setString(3, request.guest().email());
    40	            statement.setString(4, request.guest().identification().type());
    41	            statement.setString(5, request.guest().identification().number());
    42	            statement.setString(6, request.guest().identification().detail());
    43	            statement.setDate(7, Date.valueOf(request.checkIn()));
    44	            statement.setDate(8, Date.valueOf(request.checkOut()));
    45	            statement.setInt(9, request.guests());
    46	            statement.setString(10, request.ratePlan().name());
    47	            statement.setInt(11, price.nights());
    48	            statement.setBigDecimal(12, price.subtotal());
    49	            statement.setBigDecimal(13, price.discount());
    50	            statement.setBigDecimal(14, price.total());
    51	            statement.setString(15, ReservationStatus.PENDING.name());
    52	            statement.setBigDecimal(16, PriceCalculator.cents(BigDecimal.ZERO));
    53	            try (ResultSet generated = statement.executeQuery()) {
    54	                generated.next();
    55	                return new Reservation(generated.getLong("id"), request, price);
    56	            }
    57	        } catch (SQLException failure) {
    58	            if (EXCLUSION_VIOLATION.equals(failure.getSQLState())) {
    59	                throw new HotelException(ErrorCode.ROOM_UNAVAILABLE,
    60	                        "room " + request.roomNumber() + " is taken on some of those nights");
    61	            }
    62	            throw new IllegalStateException("could not save the reservation", failure);
    63	        }
    64	    }
    65	
    66	    /** Saves what changes in a reservation's life: the status, what was paid and what went back. */
    67	    void update(Reservation reservation) {
    68	        try (Connection connection = dataSource.getConnection();
    69	                PreparedStatement statement = connection.prepareStatement(
    70	                        "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
    71	            statement.setString(1, reservation.status().name());
    72	            statement.setBigDecimal(2, reservation.amountPaid());
    73	            statement.setBigDecimal(3, reservation.refund());
    74	            statement.setLong(4, reservation.id());
    75	            statement.executeUpdate();
    76	        } catch (SQLException failure) {
    77	            throw new IllegalStateException("could not save reservation " + reservation.id(), failure);
    78	        }
    79	    }
    80	
    81	    /** Whether a reservation that was not cancelled holds the room on any of the nights. */
    82	    boolean isRoomTaken(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
    83	        try (Connection connection = dataSource.getConnection();
    84	                PreparedStatement select = connection.prepareStatement(
    85	                        "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' "
    86	                                + "AND check_in < ? AND ? < check_out")) {
    87	            select.setInt(1, roomNumber);
    88	            select.setDate(2, Date.valueOf(checkOut));
    89	            select.setDate(3, Date.valueOf(checkIn));
    90	            try (ResultSet rows = select.executeQuery()) {
    91	                return rows.next();
    92	            }
    93	        } catch (SQLException failure) {
    94	            throw new IllegalStateException("could not check room " + roomNumber, failure);
    95	        }
    96	    }
    97	
    98	    public Optional<Reservation> find(long id) {
    99	        try (Connection connection = dataSource.getConnection();
   100	                PreparedStatement select = connection.prepareStatement(
   101	                        "SELECT " + COLUMNS + " FROM reservations WHERE id = ?")) {
   102	            select.setLong(1, id);
   103	            try (ResultSet rows = select.executeQuery()) {
   104	                return rows.next() ? Optional.of(read(rows)) : Optional.empty();
   105	            }
   106	        } catch (SQLException failure) {
   107	            throw new IllegalStateException("could not read reservation " + id, failure);
   108	        }
   109	    }
   110	
   111	    public List<Reservation> all() {
   112	        try (Connection connection = dataSource.getConnection();
   113	                PreparedStatement select = connection.prepareStatement(
   114	                        "SELECT " + COLUMNS + " FROM reservations ORDER BY id");
   115	                ResultSet rows = select.executeQuery()) {
   116	            List<Reservation> reservations = new ArrayList<>();
   117	            while (rows.next()) {
   118	                reservations.add(read(rows));
   119	            }
   120	            return reservations;
   121	        } catch (SQLException failure) {
   122	            throw new IllegalStateException("could not read the reservations", failure);
   123	        }
   124	    }
   125	
   126	    private static Reservation read(ResultSet row) throws SQLException {
   127	        Identification identification = Identifications.fromDatabase(
   128	                row.getString("identification_type"), row.getString("identification_number"),
   129	                row.getString("identification_detail"));
   130	        Guest guest = new Guest(row.getString("guest_name"), row.getString("guest_email"), identification);
   131	        NewReservation request = new NewReservation(
   132	                row.getInt("room_number"),
   133	                guest,
   134	                row.getDate("check_in").toLocalDate(),
   135	                row.getDate("check_out").toLocalDate(),
   136	                row.getInt("guests"),
   137	                RatePlan.valueOf(row.getString("rate_plan")));
   138	        Price price = new Price(
   139	                row.getInt("nights"), row.getBigDecimal("subtotal"), row.getBigDecimal("discount"),
   140	                row.getBigDecimal("total"));
   141	        return new Reservation(
   142	                row.getLong("id"),
   143	                request,
   144	                price,
   145	                ReservationStatus.valueOf(row.getString("status")),
   146	                row.getBigDecimal("amount_paid"),
   147	                row.getBigDecimal("refund"));
   148	    }
   149	}

