    66	        service.create(stay(201, "2027-03-10", "2027-03-13", 2, RatePlan.STANDARD));
    67	
    68	        assertEquals(ErrorCode.ROOM_UNAVAILABLE,
    69	                errorOf(() -> service.create(stay(201, "2027-03-12", "2027-03-14", 2, RatePlan.STANDARD))));
    70	        // the check-out day is free for the next guest, and another room is free on the same nights
    71	        service.create(stay(201, "2027-03-13", "2027-03-15", 2, RatePlan.STANDARD));
    72	        service.create(stay(202, "2027-03-10", "2027-03-13", 2, RatePlan.STANDARD));
